import assert from "node:assert/strict";
import { readdirSync, readFileSync } from "node:fs";
import { test } from "node:test";
import { compile } from "../src/engine/sqlgen.ts";
import { EngineError } from "../src/engine/contract.ts";
import type { PlanGraph } from "../src/engine/contract.ts";

// RFC-004: the browser-dialect lowering exists twice (Rust reference in geo-engine-browser, this TypeScript twin).
// Both are checked against the same golden fixtures, generated by the Rust reference. A drift in either fails a test.
const dir = new URL("../../crates/geo-engine-browser/tests/fixtures/lowering/", import.meta.url);
const fixtures = readdirSync(dir).filter((f) => f.endsWith(".json")).sort();

test("there are golden fixtures to compare against", () => {
  assert.ok(fixtures.length >= 11, `found ${fixtures.length}`);
});

for (const f of fixtures) {
  const fx = JSON.parse(readFileSync(new URL(f, dir), "utf8")) as {
    name: string; plan: PlanGraph; sources: Record<string, { covering: string[] | null }>; max_rows: number;
    expected: { sql?: string; files?: string[]; error_kind?: string };
  };
  test(`TypeScript lowering == Rust reference: ${fx.name}`, () => {
    const bindings = Object.fromEntries(
      Object.entries(fx.sources).map(([uri, s]) => [uri, {
        url: `/api/files/${uri}`, access: "range" as const,
        covering: s.covering ? { xmin: s.covering[0], ymin: s.covering[1], xmax: s.covering[2], ymax: s.covering[3], declared: true } : null,
      }]),
    );
    if (fx.expected.error_kind) {
      assert.throws(() => compile(fx.plan, bindings, fx.max_rows), (e: unknown) => e instanceof EngineError && e.kind === fx.expected.error_kind, fx.name);
      return;
    }
    const out = compile(fx.plan, bindings, fx.max_rows);
    assert.equal(out.sql, fx.expected.sql);
    assert.deepEqual(out.files.map((x) => x.uri), fx.expected.files);
  });
}
